import numpy as np
from math import pi
atoms=['Ni']; xyz=[np.zeros(3)]

def add(el,pos):
    atoms.append(el);xyz.append(np.array(pos));return len(atoms)-1

def basis(n):
    ref=np.array([0.,0.,1.])
    if abs(n@ref)>.85:ref=np.array([0.,1.,0.])
    u=np.cross(n,ref);u/=np.linalg.norm(u)
    v=np.cross(n,u)
    return u,v

def tetra_out(n,phase=0):
    u,v=basis(n)
    return [n/3+np.sqrt(8/9)*(np.cos(phase+2*pi*k/3)*u+np.sin(phase+2*pi*k/3)*v) for k in range(3)]
# Axial silyl ligands; equatorial trimethylphosphine ligands.
si=[]; p=[]
for n,phase in [(np.array([0.,1.,0.]),0.2),(np.array([0.,-1.,0.]),0.7)]:
    pos=n*2.28;si.append(add('Si',pos))
    for d in tetra_out(n,phase):add('F',pos+1.60*d)
for n,phase in [(np.array([-1.,0.,0.]),0.1),(np.array([.5,0.,-np.sqrt(3)/2]),0.45),(np.array([.5,0.,np.sqrt(3)/2]),-.45)]:
    pos=n*2.24;p.append(add('P',pos))
    for k,d in enumerate(tetra_out(n,phase)):
        c=pos+1.83*d;add('C',c)
        for h in tetra_out(d,0.3+k*0.55):add('H',c+1.09*h)
with open('initial.xyz','w') as f:
    f.write(f'{len(atoms)}\nNi(SiF3)2(PMe3)3; axial SiF3 and equatorial PMe3\n')
    for a,r in zip(atoms,xyz):f.write(f'{a:2s} {r[0]: .9f} {r[1]: .9f} {r[2]: .9f}\n')
print('atoms',len(atoms),'Si indices',si,'P indices',p)
